(()=>{"use strict";const $=id=>document.getElementById(id);const stages=[{"name":"Finansal Okuryazarlığın Temelleri","topics":["Finansal okuryazarlığın tanımı ve kapsamı","Finansal bilgi, davranış ve tutum","Finansal yeterlilik ve karar verme","Finansal hedeflerin belirlenmesi","Finansal ihtiyaçlar ve istekler","Finansal fırsat maliyeti","Finansal risk ve belirsizlik","Finansal sorumluluk ve öz disiplin","Finansal güvenlik ve dayanıklılık","Finansal bağımsızlık kavramı","Finansal bilgi kaynaklarının güvenilirliği","Finansal ürünleri karşılaştırma","Finansal sözleşmeleri anlama","Finansal dolandırıcılık farkındalığı","Finansal kararların kısa ve uzun vadeli sonuçları","Finansal davranışların ölçülmesi","Finansal karar günlüğü","Kişisel finansal durum değerlendirmesi","Finansal yeterlilik testleri","Kişisel finansal gelişim planı"],"lessons":[{"id":"stage1-1-1","title":"Finansal okuryazarlığın tanımı ve kapsamı","body":"Finansal okuryazarlık; bilgiyi, tutumu ve davranışı birlikte kullanarak bilinçli karar verme becerisidir.","example":"Örnek çalışma: Finansal okuryazarlığın tanımı ve kapsamı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal okuryazarlığın tanımı ve kapsamı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-2","title":"Finansal bilgi, davranış ve tutum","body":"Finansal bilgi tek başına yeterli değildir; alışkanlıklar ve para hakkındaki tutumlar gerçek sonuçları etkiler.","example":"Örnek çalışma: Finansal bilgi, davranış ve tutum için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal bilgi, davranış ve tutum hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-3","title":"Finansal yeterlilik ve karar verme","body":"Karar verirken seçenekleri, maliyetleri, belirsizlikleri ve hedeflerle uyumu karşılaştır.","example":"Örnek çalışma: Finansal yeterlilik ve karar verme için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal yeterlilik ve karar verme hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-4","title":"Finansal hedeflerin belirlenmesi","body":"Hedefi tutar, tarih, mevcut kaynak ve aylık birikim gereksinimiyle somutlaştır.","example":"Örnek çalışma: Finansal hedeflerin belirlenmesi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal hedeflerin belirlenmesi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-5","title":"Finansal ihtiyaçlar ve istekler","body":"İhtiyaç temel yaşamı destekler; istek ertelenebilir veya alternatifle karşılanabilir.","example":"Örnek çalışma: Finansal ihtiyaçlar ve istekler için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal ihtiyaçlar ve istekler hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-6","title":"Finansal fırsat maliyeti","body":"Bir seçeneği seçmenin maliyeti, vazgeçilen en iyi alternatifin değeridir.","example":"Örnek çalışma: Finansal fırsat maliyeti için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal fırsat maliyeti hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-7","title":"Finansal risk ve belirsizlik","body":"Riskte olasılıklar kısmen ölçülebilir; belirsizlikte sonuçların dağılımı net olmayabilir.","example":"Örnek çalışma: Finansal risk ve belirsizlik için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal risk ve belirsizlik hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-8","title":"Finansal sorumluluk ve öz disiplin","body":"Disiplin, harcamayı sıfırlamak değil bütçe ve önceliklerle uyumlu davranmaktır.","example":"Örnek çalışma: Finansal sorumluluk ve öz disiplin için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal sorumluluk ve öz disiplin hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-9","title":"Finansal güvenlik ve dayanıklılık","body":"Dayanıklılık, gelir kaybı ve beklenmedik giderlerde temel yükümlülükleri sürdürebilmektir.","example":"Örnek çalışma: Finansal güvenlik ve dayanıklılık için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal güvenlik ve dayanıklılık hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-10","title":"Finansal bağımsızlık kavramı","body":"Finansal bağımsızlık, yaşam giderlerini karşılamak için çalışma gelirine bağımlılığın azalmasıdır.","example":"Örnek çalışma: Finansal bağımsızlık kavramı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal bağımsızlık kavramı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-11","title":"Finansal bilgi kaynaklarının güvenilirliği","body":"Kaynağın yazarını, tarihini, yöntemini ve çıkar çatışmasını incele; resmî verileri önceliklendir.","example":"Örnek çalışma: Finansal bilgi kaynaklarının güvenilirliği için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal bilgi kaynaklarının güvenilirliği hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-12","title":"Finansal ürünleri karşılaştırma","body":"Ürünleri yalnızca getiriyle değil maliyet, risk, vade, likidite ve vergilerle karşılaştır.","example":"Örnek çalışma: Finansal ürünleri karşılaştırma için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal ürünleri karşılaştırma hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-13","title":"Finansal sözleşmeleri anlama","body":"Faiz, ücret, vade, gecikme, teminat ve fesih maddelerini imzalamadan önce oku.","example":"Örnek çalışma: Finansal sözleşmeleri anlama için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal sözleşmeleri anlama hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-14","title":"Finansal dolandırıcılık farkındalığı","body":"Şifre ve doğrulama kodu paylaşma; şüpheli bağlantı yerine kurumun resmî uygulamasını kullan.","example":"Örnek çalışma: Finansal dolandırıcılık farkındalığı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal dolandırıcılık farkındalığı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-15","title":"Finansal kararların kısa ve uzun vadeli sonuçları","body":"Bugünkü rahatlık gelecekteki nakit akışını sınırlayabilir; kısa ve uzun vade birlikte değerlendirilir.","example":"Örnek çalışma: Finansal kararların kısa ve uzun vadeli sonuçları için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal kararların kısa ve uzun vadeli sonuçları hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-16","title":"Finansal davranışların ölçülmesi","body":"Tasarruf oranı ve borç ödeme oranı gibi ölçütleri düzenli takip et.","example":"Örnek çalışma: Finansal davranışların ölçülmesi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal davranışların ölçülmesi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-17","title":"Finansal karar günlüğü","body":"Karar tarihini, varsayımları, beklenen sonucu ve gerçekleşeni not ederek hatalardan öğren.","example":"Örnek çalışma: Finansal karar günlüğü için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal karar günlüğü hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-18","title":"Kişisel finansal durum değerlendirmesi","body":"Varlıklar eksi yükümlülükler net serveti; gelir eksi giderler nakit fazlasını gösterir.","example":"Örnek çalışma: Kişisel finansal durum değerlendirmesi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kişisel finansal durum değerlendirmesi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-19","title":"Finansal yeterlilik testleri","body":"Finansal yeterlilik testleri güçlü ve gelişime açık alanları tespit etmek içindir.","example":"Örnek çalışma: Finansal yeterlilik testleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal yeterlilik testleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"},{"id":"stage1-1-20","title":"Kişisel finansal gelişim planı","body":"Ölçülebilir hedefler, aylık kontrol ve öğrenme takvimi içeren kişisel gelişim planı hazırla.","example":"Örnek çalışma: Kişisel finansal gelişim planı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kişisel finansal gelişim planı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"OECD/INFE ve CFPB finansal eğitim kaynakları"}]},{"name":"Para, Para Sistemleri ve Paranın Zaman Değeri","topics":["Paranın Tanımı ve Ekonomik İşlevleri","Paranın Tarihsel Gelişimi","Mal Para, İtibari Para ve Kaydi Para","Para Arzı ve Parasal Büyüklükler","Bankaların Para Yaratma Mekanizması","Merkez Bankasının Para Sistemindeki Rolü","Ödeme Sistemleri ve Paranın Dolaşımı","Enflasyon ve Paranın Satın Alma Gücü","Nominal Değer ve Reel Değer","Faizin Tanımı ve Ekonomik Anlamı","Basit Faiz Hesaplamaları","Bileşik Faiz ve Faizin Faizi","Paranın Zaman Değeri","Bugünkü Değer Hesaplaması","Gelecek Değer Hesaplaması","Efektif Faiz ve Faiz Dönemleri","Düzenli Ödemeler ve Anüiteler","Kredi Taksitleri ve Amortisman","İskonto Oranı ve Finansal Alternatiflerin Karşılaştırılması","Paranın Zaman Değeri: Bütünleşik Uygulama"],"lessons":[{"id":"stage1-2-1","title":"Paranın Tanımı ve Ekonomik İşlevleri","body":"Para değişim aracı, hesap birimi ve değer saklama aracı işlevlerini görür.","example":"Örnek çalışma: Paranın Tanımı ve Ekonomik İşlevleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Paranın Tanımı ve Ekonomik İşlevleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-2","title":"Paranın Tarihsel Gelişimi","body":"Takasın güçlükleri, mal para ve ardından kurumsal para sistemlerinin gelişimini hızlandırmıştır.","example":"Örnek çalışma: Paranın Tarihsel Gelişimi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Paranın Tarihsel Gelişimi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-3","title":"Mal Para, İtibari Para ve Kaydi Para","body":"Mal para içsel değere, itibari para yasal ve kurumsal kabule; kaydi para hesap kayıtlarına dayanır.","example":"Örnek çalışma: Mal Para, İtibari Para ve Kaydi Para için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Mal Para, İtibari Para ve Kaydi Para hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-4","title":"Para Arzı ve Parasal Büyüklükler","body":"Para arzı ölçütleri, kapsamlarına göre nakit ve farklı mevduat türlerini içerir.","example":"Örnek çalışma: Para Arzı ve Parasal Büyüklükler için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Para Arzı ve Parasal Büyüklükler hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-5","title":"Bankaların Para Yaratma Mekanizması","body":"Bankaların kredi vermesi mevduat yaratabilir; sermaye, likidite ve düzenlemeler süreci sınırlar.","example":"Örnek çalışma: Bankaların Para Yaratma Mekanizması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Bankaların Para Yaratma Mekanizması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-6","title":"Merkez Bankasının Para Sistemindeki Rolü","body":"Merkez bankası fiyat istikrarı ve ödeme sistemi gibi görevleri çerçevesinde para koşullarını etkiler.","example":"Örnek çalışma: Merkez Bankasının Para Sistemindeki Rolü için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Merkez Bankasının Para Sistemindeki Rolü hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-7","title":"Ödeme Sistemleri ve Paranın Dolaşımı","body":"Ödeme sistemlerinde güvenlik, mutabakat ve işlem maliyetleri önemlidir.","example":"Örnek çalışma: Ödeme Sistemleri ve Paranın Dolaşımı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Ödeme Sistemleri ve Paranın Dolaşımı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-8","title":"Enflasyon ve Paranın Satın Alma Gücü","body":"Enflasyon fiyatlar genel düzeyinin artışıdır ve sabit nominal tutarın satın alma gücünü azaltır.","example":"Örnek çalışma: Enflasyon ve Paranın Satın Alma Gücü için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Enflasyon ve Paranın Satın Alma Gücü hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-9","title":"Nominal Değer ve Reel Değer","body":"Reel değer, nominal tutarın fiyat düzeyi etkisinden arındırılmış hâlidir.","example":"Örnek çalışma: Nominal Değer ve Reel Değer için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Nominal Değer ve Reel Değer hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-10","title":"Faizin Tanımı ve Ekonomik Anlamı","body":"Faiz, paranın zaman değeri ve borçlanmanın maliyetiyle ilişkilidir.","example":"Örnek çalışma: Faizin Tanımı ve Ekonomik Anlamı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Faizin Tanımı ve Ekonomik Anlamı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-11","title":"Basit Faiz Hesaplamaları","body":"Basit faiz: anapara × dönemlik oran × dönem sayısı.","example":"Örnek çalışma: Basit Faiz Hesaplamaları için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Basit Faiz Hesaplamaları hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-12","title":"Bileşik Faiz ve Faizin Faizi","body":"Bileşik faiz: gelecek değer = anapara × (1+oran)^dönem.","example":"Örnek çalışma: Bileşik Faiz ve Faizin Faizi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Bileşik Faiz ve Faizin Faizi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-13","title":"Paranın Zaman Değeri","body":"Bugünkü ve gelecekteki eşit tutarlar, fırsat maliyeti ve enflasyon nedeniyle aynı değerde değildir.","example":"Örnek çalışma: Paranın Zaman Değeri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Paranın Zaman Değeri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-14","title":"Bugünkü Değer Hesaplaması","body":"Bugünkü değer = gelecekteki tutar / (1+oran)^dönem.","example":"Örnek çalışma: Bugünkü Değer Hesaplaması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Bugünkü Değer Hesaplaması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-15","title":"Gelecek Değer Hesaplaması","body":"Gelecek değer = bugünkü tutar × (1+oran)^dönem.","example":"Örnek çalışma: Gelecek Değer Hesaplaması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Gelecek Değer Hesaplaması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-16","title":"Efektif Faiz ve Faiz Dönemleri","body":"Faiz yılda birden fazla kez işletilirse efektif oran, nominal orandan farklı olabilir.","example":"Örnek çalışma: Efektif Faiz ve Faiz Dönemleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Efektif Faiz ve Faiz Dönemleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-17","title":"Düzenli Ödemeler ve Anüiteler","body":"Anüite, belirli aralıklarla yapılan eşit tutarlı ödeme dizisidir.","example":"Örnek çalışma: Düzenli Ödemeler ve Anüiteler için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Düzenli Ödemeler ve Anüiteler hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-18","title":"Kredi Taksitleri ve Amortisman","body":"Kredi taksitleri faiz ve anapara bileşenlerinden oluşur; kalan anapara zamanla azalır.","example":"Örnek çalışma: Kredi Taksitleri ve Amortisman için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Taksitleri ve Amortisman hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-19","title":"İskonto Oranı ve Finansal Alternatiflerin Karşılaştırılması","body":"Alternatifleri karşılaştırırken farklı tarihlerdeki nakit akışlarını aynı tarihe indirgeme gerekir.","example":"Örnek çalışma: İskonto Oranı ve Finansal Alternatiflerin Karşılaştırılması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"İskonto Oranı ve Finansal Alternatiflerin Karşılaştırılması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"},{"id":"stage1-2-20","title":"Paranın Zaman Değeri: Bütünleşik Uygulama","body":"Bugünkü değer, gelecek değer, enflasyon ve kredi maliyetini tek bir kararda birlikte uygula.","example":"Örnek çalışma: Paranın Zaman Değeri: Bütünleşik Uygulama için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Paranın Zaman Değeri: Bütünleşik Uygulama hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"TCMB eğitim yayınları ve CFA Institute finansal matematik materyalleri"}]},{"name":"Kişisel Finans ve Nakit Akışı Yönetimi","topics":["Kişisel Finans Yönetiminin Temelleri","Gelir Kavramı ve Gelir Türleri","Gelir İstikrarı ve Gelir Riskleri","Gider Kavramı ve Giderlerin Sınıflandırılması","Nakit Akışı Kavramı","Nakit Akışı ile Kâr ve Servet Arasındaki Fark","Kişisel Bütçe Hazırlama","Bütçeleme Yöntemleri","Harcama Takibi ve Kayıt Sistemi","Nakit Akışı Takvimi ve Ödeme Zamanlaması","Nakit Fazlası ve Nakit Açığı Yönetimi","Düzensiz ve Dönemsel Giderlerin Yönetimi","Harcama Önceliklendirme ve Kaynak Dağılımı","Yaşam Tarzı Enflasyonu","Tasarruf Oranı ve Birikim Kapasitesi","Borç Ödemelerinin Nakit Akışına Etkisi","Finansal Tampon ve Likidite Yönetimi","Bütçe Sapmalarının Analizi","Kişisel Finans Göstergeleri ve Aylık Kontrol","Kişisel Nakit Akışı Yönetimi: Bütünleşik Uygulama"],"lessons":[{"id":"stage1-3-1","title":"Kişisel Finans Yönetiminin Temelleri","body":"Kişisel finans yönetimi; gelir, gider, varlık, borç ve hedefleri birlikte planlamaktır.","example":"Örnek çalışma: Kişisel Finans Yönetiminin Temelleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kişisel Finans Yönetiminin Temelleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-2","title":"Gelir Kavramı ve Gelir Türleri","body":"Gelir ücret, kira, serbest çalışma veya diğer kaynaklardan gelebilir; süreklilikleri farklıdır.","example":"Örnek çalışma: Gelir Kavramı ve Gelir Türleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Gelir Kavramı ve Gelir Türleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-3","title":"Gelir İstikrarı ve Gelir Riskleri","body":"Gelir kaybı riskini sabit giderler ve likit rezervle birlikte değerlendir.","example":"Örnek çalışma: Gelir İstikrarı ve Gelir Riskleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Gelir İstikrarı ve Gelir Riskleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-4","title":"Gider Kavramı ve Giderlerin Sınıflandırılması","body":"Giderleri zorunlu/isteğe bağlı ve sabit/değişken olarak ayır.","example":"Örnek çalışma: Gider Kavramı ve Giderlerin Sınıflandırılması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Gider Kavramı ve Giderlerin Sınıflandırılması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-5","title":"Nakit Akışı Kavramı","body":"Nakit akışı belirli dönemde tahsil edilen para eksi ödenen paradır.","example":"Örnek çalışma: Nakit Akışı Kavramı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Nakit Akışı Kavramı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-6","title":"Nakit Akışı ile Kâr ve Servet Arasındaki Fark","body":"Kârlı görünmek nakit sıkıntısı yaşanmayacağını göstermez; servet de nakit değildir.","example":"Örnek çalışma: Nakit Akışı ile Kâr ve Servet Arasındaki Fark için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Nakit Akışı ile Kâr ve Servet Arasındaki Fark hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-7","title":"Kişisel Bütçe Hazırlama","body":"Bütçede beklenen gelirleri ve harcamaları önceden eşleştir.","example":"Örnek çalışma: Kişisel Bütçe Hazırlama için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kişisel Bütçe Hazırlama hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-8","title":"Bütçeleme Yöntemleri","body":"Sıfır tabanlı bütçe, zarf yöntemi ve oran temelli bütçeleme farklı disiplinler sunar.","example":"Örnek çalışma: Bütçeleme Yöntemleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Bütçeleme Yöntemleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-9","title":"Harcama Takibi ve Kayıt Sistemi","body":"Harcama kayıtları küçük ve tekrarlanan maliyetlerin görünmesini sağlar.","example":"Örnek çalışma: Harcama Takibi ve Kayıt Sistemi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Harcama Takibi ve Kayıt Sistemi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-10","title":"Nakit Akışı Takvimi ve Ödeme Zamanlaması","body":"Ödemelerin vadesi ile gelirin geliş tarihi farklıysa geçici nakit açığı oluşabilir.","example":"Örnek çalışma: Nakit Akışı Takvimi ve Ödeme Zamanlaması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Nakit Akışı Takvimi ve Ödeme Zamanlaması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-11","title":"Nakit Fazlası ve Nakit Açığı Yönetimi","body":"Nakit fazlası hedeflere ayrılabilir; açık ise öncelikle nedeni ve süresi açısından incelenir.","example":"Örnek çalışma: Nakit Fazlası ve Nakit Açığı Yönetimi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Nakit Fazlası ve Nakit Açığı Yönetimi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-12","title":"Düzensiz ve Dönemsel Giderlerin Yönetimi","body":"Yıllık veya dönemsel giderler için aylık karşılık ayırmak sürprizleri azaltır.","example":"Örnek çalışma: Düzensiz ve Dönemsel Giderlerin Yönetimi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Düzensiz ve Dönemsel Giderlerin Yönetimi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-13","title":"Harcama Önceliklendirme ve Kaynak Dağılımı","body":"Zorunlu ihtiyaçları, borç yükümlülüklerini ve hedefleri birlikte önceliklendir.","example":"Örnek çalışma: Harcama Önceliklendirme ve Kaynak Dağılımı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Harcama Önceliklendirme ve Kaynak Dağılımı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-14","title":"Yaşam Tarzı Enflasyonu","body":"Gelir arttıkça giderlerin aynı hızda artması birikim kapasitesini sınırlayabilir.","example":"Örnek çalışma: Yaşam Tarzı Enflasyonu için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Yaşam Tarzı Enflasyonu hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-15","title":"Tasarruf Oranı ve Birikim Kapasitesi","body":"Tasarruf oranı = (gelir−tüketim giderleri)/gelir ×100.","example":"Örnek çalışma: Tasarruf Oranı ve Birikim Kapasitesi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Tasarruf Oranı ve Birikim Kapasitesi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-16","title":"Borç Ödemelerinin Nakit Akışına Etkisi","body":"Borç taksitleri nakit çıkışıdır; yeni borç, gelecekteki serbest nakdi azaltır.","example":"Örnek çalışma: Borç Ödemelerinin Nakit Akışına Etkisi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Borç Ödemelerinin Nakit Akışına Etkisi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-17","title":"Finansal Tampon ve Likidite Yönetimi","body":"Likit tampon, beklenmedik giderlerde varlıkları zararına satma ihtiyacını azaltır.","example":"Örnek çalışma: Finansal Tampon ve Likidite Yönetimi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal Tampon ve Likidite Yönetimi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-18","title":"Bütçe Sapmalarının Analizi","body":"Bütçe sapması = gerçekleşen tutar − planlanan tutar; nedenini incele.","example":"Örnek çalışma: Bütçe Sapmalarının Analizi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Bütçe Sapmalarının Analizi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-19","title":"Kişisel Finans Göstergeleri ve Aylık Kontrol","body":"Nakit fazlası, borç ödeme oranı ve acil fon süresini aylık takip et.","example":"Örnek çalışma: Kişisel Finans Göstergeleri ve Aylık Kontrol için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kişisel Finans Göstergeleri ve Aylık Kontrol hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"},{"id":"stage1-3-20","title":"Kişisel Nakit Akışı Yönetimi: Bütünleşik Uygulama","body":"Gelir takvimi, giderler, borçlar ve hedefleri 12 aylık bir planla birleştir.","example":"Örnek çalışma: Kişisel Nakit Akışı Yönetimi: Bütünleşik Uygulama için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kişisel Nakit Akışı Yönetimi: Bütünleşik Uygulama hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB bütçe ve nakit akışı araçları"}]},{"name":"Tasarruf, Birikim ve Finansal Güvenlik","topics":["Tasarrufun Tanımı ve Ekonomik Önemi","Tasarruf ile Birikim Arasındaki Fark","Tasarruf Alışkanlığı ve Finansal Disiplin","Finansal Hedefler İçin Birikim Planı","Önce Kendine Öde Yaklaşımı","Acil Durum Fonu","Acil Durum Fonunun Kullanım Kuralları","Likidite ve Birikimlere Erişim","Enflasyona Karşı Birikimin Korunması","Birikim Araçlarını Değerlendirme Ölçütleri","Kısa, Orta ve Uzun Vadeli Birikim","Otomatik Birikim Sistemleri","Beklenmedik Gelirlerin Yönetimi","Finansal Dayanıklılık ve Gelir Kaybına Hazırlık","Birikimde Risk ve Güvenlik Dengesi","Birikimlerin Çeşitlendirilmesi","Birikimlerde Vergi, Ücret ve Kesintiler","Birikimlerin Korunmasında Dijital Güvenlik","Finansal Güvenlik Planının Ölçülmesi","Tasarruf ve Finansal Güvenlik: Bütünleşik Uygulama"],"lessons":[{"id":"stage1-4-1","title":"Tasarrufun Tanımı ve Ekonomik Önemi","body":"Tasarruf, kullanılabilir gelirin tüketilmeyen kısmıdır; gelecekte seçenek yaratır.","example":"Örnek çalışma: Tasarrufun Tanımı ve Ekonomik Önemi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Tasarrufun Tanımı ve Ekonomik Önemi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-2","title":"Tasarruf ile Birikim Arasındaki Fark","body":"Tasarruf dönemsel akış, birikim zaman içinde oluşan stoktur.","example":"Örnek çalışma: Tasarruf ile Birikim Arasındaki Fark için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Tasarruf ile Birikim Arasındaki Fark hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-3","title":"Tasarruf Alışkanlığı ve Finansal Disiplin","body":"Gerçekçi ve düzenli küçük tutarlar, sürdürülemeyen büyük hedeflerden yararlı olabilir.","example":"Örnek çalışma: Tasarruf Alışkanlığı ve Finansal Disiplin için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Tasarruf Alışkanlığı ve Finansal Disiplin hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-4","title":"Finansal Hedefler İçin Birikim Planı","body":"Hedef tutarından mevcut birikimi çıkarıp kalan aylara böl.","example":"Örnek çalışma: Finansal Hedefler İçin Birikim Planı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal Hedefler İçin Birikim Planı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-5","title":"Önce Kendine Öde Yaklaşımı","body":"Gelir geldiğinde zorunlu ödemeleri aksatmadan planlanan birikimi ayır.","example":"Örnek çalışma: Önce Kendine Öde Yaklaşımı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Önce Kendine Öde Yaklaşımı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-6","title":"Acil Durum Fonu","body":"Acil durum fonu, beklenmedik önemli giderler ve gelir kaybı için erişilebilir rezervdir.","example":"Örnek çalışma: Acil Durum Fonu için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Acil Durum Fonu hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-7","title":"Acil Durum Fonunun Kullanım Kuralları","body":"Fon kullanımında giderin beklenmedik, önemli ve ertelenemez olup olmadığını değerlendir.","example":"Örnek çalışma: Acil Durum Fonunun Kullanım Kuralları için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Acil Durum Fonunun Kullanım Kuralları hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-8","title":"Likidite ve Birikimlere Erişim","body":"Likidite, varlığı hızla ve büyük değer kaybı olmadan kullanılabilir paraya dönüştürmektir.","example":"Örnek çalışma: Likidite ve Birikimlere Erişim için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Likidite ve Birikimlere Erişim hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-9","title":"Enflasyona Karşı Birikimin Korunması","body":"Reel getiri = (1+nominal getiri)/(1+enflasyon) − 1.","example":"Örnek çalışma: Enflasyona Karşı Birikimin Korunması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Enflasyona Karşı Birikimin Korunması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-10","title":"Birikim Araçlarını Değerlendirme Ölçütleri","body":"Birikim araçlarını risk, vade, maliyet, likidite ve güvence yönünden incele.","example":"Örnek çalışma: Birikim Araçlarını Değerlendirme Ölçütleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Birikim Araçlarını Değerlendirme Ölçütleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-11","title":"Kısa, Orta ve Uzun Vadeli Birikim","body":"Yakın vadede gereken kaynaklarda erişilebilirlik ve değer oynaklığı kritiktir.","example":"Örnek çalışma: Kısa, Orta ve Uzun Vadeli Birikim için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kısa, Orta ve Uzun Vadeli Birikim hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-12","title":"Otomatik Birikim Sistemleri","body":"Otomatik aktarım tasarruf alışkanlığını destekler; yetersiz bakiye riskini kontrol et.","example":"Örnek çalışma: Otomatik Birikim Sistemleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Otomatik Birikim Sistemleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-13","title":"Beklenmedik Gelirlerin Yönetimi","body":"Prim gibi tek seferlik geliri kalıcı gelir varsaymadan hedeflere dağıt.","example":"Örnek çalışma: Beklenmedik Gelirlerin Yönetimi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Beklenmedik Gelirlerin Yönetimi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-14","title":"Finansal Dayanıklılık ve Gelir Kaybına Hazırlık","body":"Gelir düşüşü senaryosu ve gider esnekliği finansal dayanıklılığı artırır.","example":"Örnek çalışma: Finansal Dayanıklılık ve Gelir Kaybına Hazırlık için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal Dayanıklılık ve Gelir Kaybına Hazırlık hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-15","title":"Birikimde Risk ve Güvenlik Dengesi","body":"Nominal anapara korunurken enflasyon nedeniyle reel değer düşebilir.","example":"Örnek çalışma: Birikimde Risk ve Güvenlik Dengesi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Birikimde Risk ve Güvenlik Dengesi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-16","title":"Birikimlerin Çeşitlendirilmesi","body":"Çeşitlendirme tek bir riske bağımlılığı azaltabilir ama bütün riskleri yok etmez.","example":"Örnek çalışma: Birikimlerin Çeşitlendirilmesi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Birikimlerin Çeşitlendirilmesi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-17","title":"Birikimlerde Vergi, Ücret ve Kesintiler","body":"Net kazanç = brüt getiri − vergi ve diğer kesintiler.","example":"Örnek çalışma: Birikimlerde Vergi, Ücret ve Kesintiler için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Birikimlerde Vergi, Ücret ve Kesintiler hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-18","title":"Birikimlerin Korunmasında Dijital Güvenlik","body":"Benzersiz parola, çok faktörlü doğrulama ve resmî kanallar birikimleri korumaya yardım eder.","example":"Örnek çalışma: Birikimlerin Korunmasında Dijital Güvenlik için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Birikimlerin Korunmasında Dijital Güvenlik hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-19","title":"Finansal Güvenlik Planının Ölçülmesi","body":"Acil fon süresi = likit fon / aylık temel gider.","example":"Örnek çalışma: Finansal Güvenlik Planının Ölçülmesi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Finansal Güvenlik Planının Ölçülmesi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"},{"id":"stage1-4-20","title":"Tasarruf ve Finansal Güvenlik: Bütünleşik Uygulama","body":"Tasarruf oranı, hedefler, likidite, enflasyon ve riskleri tek bir 12 aylık planda birleştir.","example":"Örnek çalışma: Tasarruf ve Finansal Güvenlik: Bütünleşik Uygulama için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Tasarruf ve Finansal Güvenlik: Bütünleşik Uygulama hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"CFPB tasarruf rehberleri; TCMB ve SPK yayınları"}]},{"name":"Borç, Kredi ve Bankacılık Yönetimi","topics":["Borç Kavramı ve Borçlanmanın Ekonomik İşlevi","Bankacılık Sisteminin Temelleri","Banka Hesapları ve Mevduat Ürünleri","Kredi Türleri ve Kullanım Amaçları","Kredi Faizi ve Toplam Borçlanma Maliyeti","Sabit ve Değişken Faizli Krediler","Kredi Vadesi ve Taksit Planlaması","Kredi Amortismanı ve Anapara-Faiz Ayrımı","Kredi Kartlarının Çalışma Mantığı","Kredi Kartı Faizi ve Asgari Ödeme","Kredili Mevduat Hesabı ve Kısa Vadeli Borçlanma","Kredi Notu ve Kredi Değerlendirme Süreci","Borç Ödeme Kapasitesi ve Borçluluk Oranları","Borç Envanteri Oluşturma","Borç Kartopu ve Borç Çığı Yöntemleri","Erken Ödeme ve Borç Kapatma Kararları","Borç Yapılandırma ve Yeniden Finansman","Gecikme, Temerrüt ve Borç Sorunlarının Erken Yönetimi","Bankacılık Sözleşmeleri ve Finansal Tüketici Hakları","Borç ve Bankacılık Yönetimi: Bütünleşik Uygulama"],"lessons":[{"id":"stage1-5-1","title":"Borç Kavramı ve Borçlanmanın Ekonomik İşlevi","body":"Borç bugün kaynak sağlar ancak gelecekte geri ödeme yükümlülüğü doğurur.","example":"Örnek çalışma: Borç Kavramı ve Borçlanmanın Ekonomik İşlevi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Borç Kavramı ve Borçlanmanın Ekonomik İşlevi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-2","title":"Bankacılık Sisteminin Temelleri","body":"Banka bilançosunda krediler varlık, müşteri mevduatları yükümlülüktür.","example":"Örnek çalışma: Bankacılık Sisteminin Temelleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Bankacılık Sisteminin Temelleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-3","title":"Banka Hesapları ve Mevduat Ürünleri","body":"Vadesiz ve vadeli hesapların erişim, getiri ve sözleşme koşulları farklıdır.","example":"Örnek çalışma: Banka Hesapları ve Mevduat Ürünleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Banka Hesapları ve Mevduat Ürünleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-4","title":"Kredi Türleri ve Kullanım Amaçları","body":"İhtiyaç, taşıt ve konut kredilerinin maliyet, teminat ve vadeleri farklılaşabilir.","example":"Örnek çalışma: Kredi Türleri ve Kullanım Amaçları için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Türleri ve Kullanım Amaçları hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-5","title":"Kredi Faizi ve Toplam Borçlanma Maliyeti","body":"Toplam kredi maliyeti faiz, vergi ve varsa diğer ücretleri içerebilir.","example":"Örnek çalışma: Kredi Faizi ve Toplam Borçlanma Maliyeti için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Faizi ve Toplam Borçlanma Maliyeti hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-6","title":"Sabit ve Değişken Faizli Krediler","body":"Sabit faiz öngörülebilirlik sağlar; değişken faiz ödeme belirsizliği yaratabilir.","example":"Örnek çalışma: Sabit ve Değişken Faizli Krediler için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Sabit ve Değişken Faizli Krediler hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-7","title":"Kredi Vadesi ve Taksit Planlaması","body":"Uzun vade taksiti azaltabilir ancak toplam maliyeti artırabilir.","example":"Örnek çalışma: Kredi Vadesi ve Taksit Planlaması için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Vadesi ve Taksit Planlaması hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-8","title":"Kredi Amortismanı ve Anapara-Faiz Ayrımı","body":"Dönem faizi = kalan anapara × dönemlik faiz; anapara ödemesi = taksit − faiz.","example":"Örnek çalışma: Kredi Amortismanı ve Anapara-Faiz Ayrımı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Amortismanı ve Anapara-Faiz Ayrımı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-9","title":"Kredi Kartlarının Çalışma Mantığı","body":"Kredi kartı limiti gelir değildir; yapılan harcama ödeme yükümlülüğü doğurur.","example":"Örnek çalışma: Kredi Kartlarının Çalışma Mantığı için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Kartlarının Çalışma Mantığı hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-10","title":"Kredi Kartı Faizi ve Asgari Ödeme","body":"Asgari ödeme kalan kart borcunu kapatmaz; faiz koşullarını kontrol et.","example":"Örnek çalışma: Kredi Kartı Faizi ve Asgari Ödeme için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Kartı Faizi ve Asgari Ödeme hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-11","title":"Kredili Mevduat Hesabı ve Kısa Vadeli Borçlanma","body":"Kredili mevduat hesabı kısa vadeli borçtur; kullanım süresi maliyeti etkiler.","example":"Örnek çalışma: Kredili Mevduat Hesabı ve Kısa Vadeli Borçlanma için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredili Mevduat Hesabı ve Kısa Vadeli Borçlanma hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-12","title":"Kredi Notu ve Kredi Değerlendirme Süreci","body":"Kredi değerlendirmesi gelir, mevcut borç ve ödeme geçmişi gibi faktörleri içerir.","example":"Örnek çalışma: Kredi Notu ve Kredi Değerlendirme Süreci için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Kredi Notu ve Kredi Değerlendirme Süreci hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-13","title":"Borç Ödeme Kapasitesi ve Borçluluk Oranları","body":"Borç ödeme oranı = aylık borç taksitleri / aylık kullanılabilir gelir ×100.","example":"Örnek çalışma: Borç Ödeme Kapasitesi ve Borçluluk Oranları için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Borç Ödeme Kapasitesi ve Borçluluk Oranları hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-14","title":"Borç Envanteri Oluşturma","body":"Borçları kalan tutar, faiz, taksit ve son ödeme tarihiyle tek listede topla.","example":"Örnek çalışma: Borç Envanteri Oluşturma için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Borç Envanteri Oluşturma hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-15","title":"Borç Kartopu ve Borç Çığı Yöntemleri","body":"Kartopu küçük bakiyeyi, çığ yüksek faizli borcu öncelemeyi hedefler.","example":"Örnek çalışma: Borç Kartopu ve Borç Çığı Yöntemleri için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Borç Kartopu ve Borç Çığı Yöntemleri hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-16","title":"Erken Ödeme ve Borç Kapatma Kararları","body":"Erken kapamada faiz tasarrufunu, varsa maliyetleri ve likidite kaybını karşılaştır.","example":"Örnek çalışma: Erken Ödeme ve Borç Kapatma Kararları için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Erken Ödeme ve Borç Kapatma Kararları hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-17","title":"Borç Yapılandırma ve Yeniden Finansman","body":"Yapılandırma taksiti azaltırken toplam geri ödemeyi artırabilir.","example":"Örnek çalışma: Borç Yapılandırma ve Yeniden Finansman için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Borç Yapılandırma ve Yeniden Finansman hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-18","title":"Gecikme, Temerrüt ve Borç Sorunlarının Erken Yönetimi","body":"Ödeme güçlüğünde açığı hesapla ve finansal kurumla resmî kanaldan erken görüş.","example":"Örnek çalışma: Gecikme, Temerrüt ve Borç Sorunlarının Erken Yönetimi için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Gecikme, Temerrüt ve Borç Sorunlarının Erken Yönetimi hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-19","title":"Bankacılık Sözleşmeleri ve Finansal Tüketici Hakları","body":"Sözleşmede faiz, toplam maliyet, gecikme, teminat ve başvuru yollarını incele.","example":"Örnek çalışma: Bankacılık Sözleşmeleri ve Finansal Tüketici Hakları için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Bankacılık Sözleşmeleri ve Finansal Tüketici Hakları hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"},{"id":"stage1-5-20","title":"Borç ve Bankacılık Yönetimi: Bütünleşik Uygulama","body":"Yeni kredi kararını bütçe, toplam maliyet ve gelir düşüşü senaryosuyla test et.","example":"Örnek çalışma: Borç ve Bankacılık Yönetimi: Bütünleşik Uygulama için 40.000 TL aylık gelir, 28.000 TL temel gider ve 5.000 TL mevcut ödeme varsay. Konunun bu bütçeye etkisini rakamlarla ve gerekçeyle değerlendir.","homework":"Borç ve Bankacılık Yönetimi: Bütünleşik Uygulama hakkında kendi hayatından veya varsayımsal bir örnek seç. Tanımını, sayısal etkisini, iki alternatifi ve risklerini yaz.","source":"BDDK, TCMB, TBB ve tüketici mevzuatı"}]}];const lessons=stages.flatMap((g,ci)=>g.lessons.map((l,ti)=>({...l,ci,ti})));let active=0,selected=null,query="",answer=-1;const esc=x=>String(x).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));const get=(id,k)=>window.AcademyStore.get("finance",id,k);const put=(id,k,v)=>window.AcademyStore.save("finance",id,k,v);function stats(){const n=lessons.filter(l=>get(l.id,"done")==="1").length;$("finTotal").textContent="100";$("finCompleted").textContent=n;$("finPercent").textContent="%"+n}function cats(){$("finCategories").innerHTML='<p><strong>1. Aşama — Temel Finansal Yetkinlik</strong></p>'+stages.map((g,i)=>'<button class="academy-cat '+(active===i?"active":"")+'" data-cat="'+i+'"><span>'+(i+1)+'. '+esc(g.name)+'</span><small>20 konu</small></button>').join("");$("finCategories").querySelectorAll("button").forEach(b=>b.onclick=()=>{active=+b.dataset.cat;query="";$("finSearch").value="";cats();catalog()})}function catalog(){let g=stages[active];$("finCategoryTitle").textContent="1. Aşama / "+(active+1)+". Ana Başlık: "+g.name;$("finCategoryDesc").textContent="20 konu · Konular arasında serbest geçiş";let found=lessons.filter(l=>query?(l.title+" "+stages[l.ci].name).toLocaleLowerCase("tr").includes(query):l.ci===active);$("finLessons").innerHTML=found.map(l=>'<button class="academy-lesson" data-id="'+l.id+'"><span><b>'+(l.ti+1)+'. '+esc(l.title)+'</b><small>'+(l.ci+1)+'. Ana Başlık</small></span><span>'+(get(l.id,"done")==="1"?"✓ Tamamlandı":"Dersi aç →")+'</span></button>').join("")||"<p>Sonuç bulunamadı.</p>";$("finLessons").querySelectorAll("button").forEach(b=>b.onclick=()=>open(b.dataset.id))}function open(id){let l=lessons.find(x=>x.id===id);if(!l)return;selected=l;active=l.ci;answer=-1;let g=stages[l.ci];$("finCatalog").classList.add("hidden");$("finLessonView").classList.remove("hidden");$("finBreadcrumb").textContent="1. Aşama / "+(l.ci+1)+". Ana Başlık / "+(l.ti+1)+". Konu";$("finLessonTitle").textContent=l.title;$("finArticle").innerHTML='<p class="academy-lead">'+esc(l.body)+'</p><section><h3>Konu anlatımı</h3><p>'+esc(l.body)+'</p><p>Karar verirken konunun tanımını, uygulanabilirliğini, maliyetlerini, fırsat maliyetini ve belirsizliklerini birlikte ele al. Kişisel koşullar ve sözleşme hükümleri sonuçları değiştirebilir.</p></section><section><h3>Çözümlü çalışma</h3><p>'+esc(l.example)+'</p><p>Örnek bütçede diğer giderler hariç kalan tutar: 40.000 − 28.000 − 5.000 = <strong>7.000 TL</strong>. Bu tutar yeni yükümlülükler için otomatik olarak güvenli kabul edilemez.</p></section><section><h3>Özet</h3><p>'+esc(l.body)+'</p></section><section><h3>Kaynak önerisi</h3><p>'+esc(l.source)+'</p></section><p class="sub">Bu sürümde derslere konuya özel başlangıç anlatımı aktarıldı. Önceden hazırlanan uzun metinlerin, beş ayrı quiz sorusunun ve tüm çözümlü örneklerin birebir aktarımı henüz tamamlanmadı.</p>';$("finQuestion").textContent=l.title+" konusunda doğru değerlendirme hangisidir?";let options=[l.body,"Tek bir gösterge veya sosyal medya iddiası her durumda kesin sonuç verir.","Risk, maliyet ve kişisel koşullar hiçbir finansal kararda önemli değildir."];$("finOptions").innerHTML=options.map((x,i)=>'<label class="academy-option"><input type="radio" name="finQuiz" value="'+i+'"> '+esc(x)+'</label>').join("");$("finFeedback").textContent=get(l.id,"quiz")==="1"?"Bu soruyu daha önce doğru cevapladın.":"";$("finAssignment").textContent=l.homework;$("finAnswer").value=get(l.id,"answer")||"";$("finComplete").textContent=get(l.id,"done")==="1"?"Tamamlandı ✓":"Dersi tamamla";$("finSaveFeedback").textContent="";let nav=document.getElementById("finTopicNav");if(!nav){nav=document.createElement("div");nav.id="finTopicNav";nav.className="academy-actions";$("finBreadcrumb").before(nav)}nav.innerHTML='<button type="button" class="secondary" id="finPrevTopic" '+(l.ti===0&&l.ci===0?"disabled":"")+'>← Önceki konu</button><button type="button" class="secondary" id="finNextTopic" '+(l.ti===19&&l.ci===4?"disabled":"")+'>Sonraki konu →</button>';document.getElementById("finPrevTopic").onclick=()=>open(lessons[lessons.findIndex(x=>x.id===l.id)-1]?.id);document.getElementById("finNextTopic").onclick=()=>open(lessons[lessons.findIndex(x=>x.id===l.id)+1]?.id);$("finLessonView").scrollIntoView({behavior:"smooth",block:"start"})}function show(mode){let finance=$("financeAcademyView"),journey=$("journeyView"),coach=$("coachView");if(!finance)return;finance.classList.toggle("hidden",mode!=="finance");journey?.classList.toggle("hidden",mode!=="journey");coach?.classList.add("hidden");document.querySelectorAll("#appView main > :not(#financeAcademyView):not(#journeyView):not(#coachView)").forEach(el=>el.classList.toggle("mode-hidden",mode!=="ledger"));["modeLedger","modeCoach","modeJourney"].forEach((id,i)=>$(id)?.classList.toggle("active",["ledger","finance","journey"][i]===mode))}document.addEventListener("DOMContentLoaded",()=>{window.AcademyStore.load().then(()=>{cats();catalog();stats()}).catch(e=>{console.error(e);cats();catalog();stats()});$("finSearch").oninput=e=>{query=e.target.value.trim().toLocaleLowerCase("tr");catalog()};$("finBack").onclick=()=>{$("finLessonView").classList.add("hidden");$("finCatalog").classList.remove("hidden");cats();catalog()};$("finCheck").onclick=async()=>{let v=document.querySelector('input[name="finQuiz"]:checked');if(!v){$("finFeedback").textContent="Bir cevap seç.";return}let ok=v.value==="0";if(ok)try{await put(selected.id,"quiz","1")}catch(e){$("finFeedback").textContent="Kayıt hatası: "+e.message;return}$("finFeedback").textContent=ok?"Doğru. Konunun temel ilkesini seçtin.":"Yanlış. Konu anlatımını yeniden incele."};$("finSave").onclick=async()=>{if(!selected)return;try{await put(selected.id,"answer",$("finAnswer").value);$("finSaveFeedback").textContent="Notlar kaydedildi."}catch(e){$("finSaveFeedback").textContent="Kayıt hatası: "+e.message}};$("finComplete").onclick=async()=>{if(!selected)return;if(get(selected.id,"quiz")!=="1"){$("finSaveFeedback").textContent="Önce testi doğru cevapla.";return}if(!$("finAnswer").value.trim()){$("finSaveFeedback").textContent="Önce ödevi yaz.";return}try{await put(selected.id,"answer",$("finAnswer").value);await put(selected.id,"done","1");$("finComplete").textContent="Tamamlandı ✓";$("finSaveFeedback").textContent="Ders kaydedildi.";stats()}catch(e){$("finSaveFeedback").textContent="Kayıt hatası: "+e.message}};$("modeCoach")?.addEventListener("click",()=>show("finance"));$("modeLedger")?.addEventListener("click",()=>show("ledger"));$("modeJourney")?.addEventListener("click",()=>show("journey"))})})();